-- ----------------------------
-- View structure for system_vw_datatable_master_role
-- ----------------------------
DROP VIEW IF EXISTS `system_vw_datatable_master_role`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `system_vw_datatable_master_role` AS select `sr`.`id` AS `id`,`sr`.`role` AS `role`,`sr`.`status` AS `state`,`sr`.`satker_id` AS `kode_satker`,`ms`.`nama_satker` AS `nama_satker` from (`system_role` `sr` left join `master_satker` `ms` on((`sr`.`satker_id` = `ms`.`kode_satker`)));

-- ----------------------------
-- View structure for system_vw_datatable_master_user
-- ----------------------------
DROP VIEW IF EXISTS `system_vw_datatable_master_user`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `system_vw_datatable_master_user` AS select `su`.`id` AS `id`,`su`.`satker_id` AS `satker_id`,`su`.`username` AS `username`,`su`.`nip` AS `nip`,`su`.`nama` AS `nama`,`su`.`password` AS `PASSWORD`,`su`.`pass_enc` AS `pass_enc`,`su`.`id_role` AS `id_role`,`sr`.`role` AS `role`,`sr`.`status` AS `STATUS`,`su`.`state` AS `state`,`ms`.`kode_satker` AS `kode_satker`,`ms`.`nama_satker` AS `nama_satker` from ((`system_user` `su` join `system_role` `sr` on((`su`.`id_role` = `sr`.`id`))) left join `master_satker` `ms` on((`su`.`satker_id` = `ms`.`kode_satker`))) where (1 = 1);

-- ----------------------------
-- Procedure structure for sp_proses_periode
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_proses_periode`;
delimiter ;;
CREATE PROCEDURE `sp_proses_periode`(IN vm INT,
    IN vy INT)
BEGIN
    DECLARE stts INT DEFAULT 0;

    -- Insert akan berhasil hanya jika (periode_m, periode_y) belum ada
    INSERT INTO periodeaktif (periode_m, periode_y, is_closed, create_dt)
    VALUES (vm, vy, 0, NOW())
    ON DUPLICATE KEY UPDATE
        -- tidak mengubah data, hanya “memicu” jalur duplicate
        periode_m = periode_m;

    IF ROW_COUNT() = 1 THEN
        SET stts = 1;   -- baris baru berhasil diinsert
    ELSE
        SET stts = 0;   -- sudah ada (kena duplicate key)
    END IF;

    SELECT stts AS stts;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for system_sp_set_menu_aksi
-- ----------------------------
DROP PROCEDURE IF EXISTS `system_sp_set_menu_aksi`;
delimiter ;;
CREATE PROCEDURE `system_sp_set_menu_aksi`(IN p_RoleID INT,
    IN p_MenuID INT,
    IN p_Value INT,
    IN p_Type VARCHAR(255))
BEGIN
    DECLARE v_privilegeFound INT DEFAULT 0;
    DECLARE v_columnName VARCHAR(50);
    DECLARE v_rowsAffected INT DEFAULT 0;
    -- Cari apakah privilege sudah ada
    SELECT IFNULL(id, 0) INTO v_privilegeFound
    FROM system_menu_otorisasi
    WHERE id_menu = p_MenuID AND id_role = p_RoleID
    LIMIT 1;
    -- Validasi: jika record tidak ditemukan, kembalikan error
    IF v_privilegeFound = 0 THEN
        SELECT 0 AS last_id, 0 AS state;
    ELSE
        -- Mapping type ke column name
        CASE p_Type
            WHEN 'input' THEN
                UPDATE system_menu_otorisasi 
                SET hak_input = p_Value 
                WHERE id_menu = p_MenuID AND id_role = p_RoleID;
                
            WHEN 'ubah' THEN
                UPDATE system_menu_otorisasi 
                SET hak_ubah = p_Value 
                WHERE id_menu = p_MenuID AND id_role = p_RoleID;
                
            WHEN 'hapus' THEN
                UPDATE system_menu_otorisasi 
                SET hak_hapus = p_Value 
                WHERE id_menu = p_MenuID AND id_role = p_RoleID;
                
            WHEN 'cetak' THEN
                UPDATE system_menu_otorisasi 
                SET hak_cetak = p_Value 
                WHERE id_menu = p_MenuID AND id_role = p_RoleID;
                
            WHEN 'verifikasi' THEN
                UPDATE system_menu_otorisasi 
                SET hak_verifikasi = p_Value 
                WHERE id_menu = p_MenuID AND id_role = p_RoleID;
                
            WHEN 'unverifikasi' THEN
                UPDATE system_menu_otorisasi 
                SET hak_unverifikasi = p_Value 
                WHERE id_menu = p_MenuID AND id_role = p_RoleID;
                
            ELSE
                -- Type tidak valid
                SELECT 0 AS last_id, 0 AS state;
        END CASE;
        -- Cek apakah ada row yang terupdate
        SET v_rowsAffected = ROW_COUNT();
        
        IF v_rowsAffected > 0 THEN
            SELECT 1 AS state;
        ELSE
            SELECT 0 AS last_id, 0 AS state;
        END IF;
        
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for system_sp_set_menu_hak
-- ----------------------------
DROP PROCEDURE IF EXISTS `system_sp_set_menu_hak`;
delimiter ;;
CREATE PROCEDURE `system_sp_set_menu_hak`(IN p_RoleID INT,
    IN p_MenuID INT,
    IN p_Value INT)
BEGIN
    DECLARE v_privilegeFound INT DEFAULT 0;
    DECLARE v_insertedId INT;
    -- Cari apakah privilege sudah ada
    SELECT IFNULL(id, 0) INTO v_privilegeFound
    FROM system_menu_otorisasi
    WHERE id_menu = p_MenuID AND id_role = p_RoleID
    LIMIT 1;
    IF p_Value = 1 THEN
        -- Jika ingin menambahkan hak akses
        IF v_privilegeFound = 0 THEN
            INSERT INTO system_menu_otorisasi (id_menu, id_role)
            VALUES (p_MenuID, p_RoleID);
            
            SET v_insertedId = LAST_INSERT_ID();
            SELECT v_insertedId AS last_id, 1 AS state;
        ELSE
            -- Sudah ada, kembalikan state 0
            SELECT 0 AS last_id, 0 AS state;
        END IF;
        
    ELSEIF p_Value = 0 THEN
        -- Jika ingin menghapus hak akses
        IF v_privilegeFound != 0 THEN
            DELETE FROM system_menu_otorisasi 
            WHERE id_menu = p_MenuID AND id_role = p_RoleID;
            
            SELECT v_privilegeFound AS last_id, 1 AS state;
        ELSE
            -- Tidak ditemukan, kembalikan state 0
            SELECT 0 AS last_id, 0 AS state;
        END IF;
    ELSE
        -- Value tidak valid
        SELECT 0 AS last_id, 0 AS state;
    END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for trans_jurnal_sp_insert_ttd_jurnal_from_lap
-- ----------------------------
DROP PROCEDURE IF EXISTS `trans_jurnal_sp_insert_ttd_jurnal_from_lap`;
delimiter ;;
CREATE PROCEDURE `trans_jurnal_sp_insert_ttd_jurnal_from_lap`(IN p_reff_jurnal        VARCHAR(100),   -- jenis_laporan di ttd_lap / jenis_lap di ref
    IN p_id_data            INT,            -- id_data di ttd_jurnal
    IN p_jt_id              INT,            -- jenis jurnal
    IN p_user_input         VARCHAR(100),   -- boleh NULL
    IN p_no_ref_verifikasi  VARCHAR(100))
BEGIN
    -- Hapus data ttd_jurnal yang sudah ada untuk kombinasi jt_id dan id_data yang sama
    DELETE FROM ttd_jurnal
    WHERE jt_id = p_jt_id
      AND id_data = p_id_data;
      
    INSERT INTO ttd_jurnal
    (
        jt_id,
        id_data,
        urutan_ke,
        keterangan,
        jabatan,
        nama,
        nup,
        create_dt,
        update_dt,
        user_input,
        is_ttd,
        no_ref_anggaran_verifikasi
    )
    SELECT
        p_jt_id,
        p_id_data,
        l.urutan_ke,
        l.keterangan,
        l.jabatan,
        l.nama,
        l.nup,
        NOW(),          -- SYSDATETIME() padanan
        NULL,
        p_user_input,
        0,
        p_no_ref_verifikasi
    FROM ttd_ref_pengesahan AS l
    WHERE l.jenis_lap = p_reff_jurnal
      AND l.jt_id = p_jt_id;
      
    IF ROW_COUNT() > 0 THEN
        SELECT 1 AS stts;
    ELSE
        SELECT 0 AS stts;
    END IF;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
